#define BUFFER_MAX_LENGTH 16

nodespace {
    using ParserState = xod::json_parser::ParserState;

    enum class StackItem : uint8_t {
      OBJECT = 0,
      ARRAY = 1,
      KEY = 2,
      STRING = 3
    };

    bool isFirstCharInNumber(char c) {
        return (c >= '0' && c <= '9') || c == '-';
    }
