            return;

        auto socket = getValue<input_SOCK>(ctx);
        auto client = EthernetClient(socket);
        auto msg = getValue<input_MSG>(ctx);

        size_t lastWriteSize;

        for (auto it = msg->iterate(); it; ++it) {
            lastWriteSize = client.write((char)*it);
            if (lastWriteSize == 0) {
                raiseError(ctx);
                return;
